<?php /** @var \Sysfera\Plugin $sf @var \SysferaStoragerent\Ctx $ctx @var string $lang @var array $i @var array $items @var array $allocs @var array $adjs @var array $docs @var array $tenant @var ?array $contract @var bool $canWrite @var bool $tenantView @var array $adjKinds */
require __DIR__ . '/_nav.php'; $id = (int)$i['id']; $tt = fn(string $k, array $v = []) => $sf->t($k, $v); ?>
<p><a href="<?= e($sf->url($tenantView ? '/portal' : '/invoices')) ?>">← <?= e($sf->t($tenantView ? 'portal' : 'wrms_invoices')) ?></a></p>
<div class="card"><div class="row sr-between"><div><h2 style="margin:0"><?= e($i['number']) ?> <span class="badge <?= e(sr_cls($i['status'])) ?>"><?= e($sf->t('st_' . $i['status'])) ?></span><?php if ($i['late'] && $i['status'] !== 'overdue'): ?> <span class="badge bad"><?= e($sf->t('st_late')) ?></span><?php endif; ?></h2>
  <p class="muted"><?= e($tenant['name'] ?? '') ?> · <a href="<?= e($sf->url('/contract/' . $i['contract_id'])) ?>"><?= e($i['contract_number']) ?></a><?= $i['period_start'] ? ' · ' . e(sr_d($i['period_start'])) . ' – ' . e(sr_d($i['period_end'])) : '' ?></p></div>
  <a class="btn sm" href="<?= e($sf->url('/invoice/' . $id . '/print')) ?>" target="_blank"><?= e($sf->t('print_pdf')) ?></a></div>
  <p><?= e($sf->t('col_issue_date')) ?>: <?= e(sr_d($i['issue_date'])) ?> · <?= e($sf->t('col_due_date')) ?>: <b><?= e(sr_d($i['due_date'])) ?></b><?= $i['reason'] !== '' && $i['kind'] === 'manual' ? ' · ' . e($sf->t('f_reason')) . ': ' . e($i['reason']) : '' ?></p>
  <table><thead><tr><th><?= e($sf->t('f_description')) ?></th><th class="r"><?= e($sf->t('col_qty')) ?></th><th class="r"><?= e($sf->t('f_amount')) ?></th></tr></thead><tbody>
  <?php foreach ($items as $it): ?><tr><td><?= e(\SysferaStoragerent\Text::item($it, $tt)) ?></td><td class="r"><?= e(sr_num($it['qty'])) ?></td><td class="r"><?= e(sr_m($it['amount'], $lang)) ?></td></tr><?php endforeach; ?></tbody>
  <tfoot><tr><td colspan="2"><?= e($sf->t('inv_net')) ?></td><td class="r"><?= e(sr_m($i['net'], $lang)) ?></td></tr><tr><td colspan="2"><?= e($sf->t('inv_vat')) ?></td><td class="r"><?= e(sr_m($i['vat'], $lang)) ?></td></tr><tr><td colspan="2"><b><?= e($sf->t('col_total')) ?></b></td><td class="r"><b><?= e(sr_m($i['total'], $lang)) ?></b></td></tr>
  <tr><td colspan="2"><?= e($sf->t('inv_settled')) ?></td><td class="r"><?= e(sr_m($i['settled'], $lang)) ?></td></tr><tr><td colspan="2"><b><?= e($sf->t('col_outstanding')) ?></b></td><td class="r <?= $i['late'] ? 'bad-t' : '' ?>"><b><?= e(sr_m($i['outstanding'], $lang)) ?></b></td></tr></tfoot></table>
  <?php if ($i['penalty_accrued'] > 0): ?><p class="sm"><?= e($sf->t('inv_penalty_accrued', ['amount' => sr_m($i['penalty_accrued'], $lang), 'unbilled' => sr_m($i['penalty_unbilled'], $lang)])) ?></p><?php endif; ?></div>
<?php if ($allocs || $adjs): ?><div class="card"><h3><?= e($sf->t('inv_history')) ?></h3><table><tbody>
  <?php foreach ($allocs as $a): ?><tr><td><?= e(sr_d($a['pay_date'])) ?></td><td><?= e($sf->t('pm_' . $a['method'])) ?> <?= e($a['reference']) ?></td><td class="r"><?= e(sr_m($a['amount'], $lang)) ?></td></tr><?php endforeach; ?>
  <?php foreach ($adjs as $a): ?><tr><td><?= e(sr_d($a['adj_date'])) ?></td><td><?= e($sf->t('adj_' . $a['kind'])) ?>: <?= e($a['reason']) ?></td><td class="r"><?= e(sr_m($a['amount'], $lang)) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
<?php if ($canWrite): ?><div class="grid2">
<?php if ($i['stored_status'] === 'draft'): ?><form method="post" action="<?= e($sf->url('/invoice/' . $id . '/do')) ?>" class="card"><?= csrf_field() ?><input type="hidden" name="do" value="issue"><button class="btn primary"><?= e($sf->t('inv_issue')) ?></button></form><?php endif; ?>
<?php if (!in_array($i['status'], ['draft', 'cancelled', 'paid'], true)): ?>
<form method="post" action="<?= e($sf->url('/invoice/' . $id . '/do')) ?>" class="card"><?= csrf_field() ?><input type="hidden" name="do" value="adjust"><h3><?= e($sf->t('inv_adjust')) ?></h3><p class="muted sm"><?= e($sf->t('inv_adjust_help')) ?></p>
  <?= sr_sel('kind', $sf->t('f_kind'), array_combine($adjKinds, array_map(fn($x) => $sf->t('adj_' . $x), $adjKinds)), 'writeoff') ?><div class="sr-2"><?= sr_in('amount', $sf->t('f_amount'), \SysferaStoragerent\Billing::dec((int)$i['outstanding']), 'text', 'inputmode="decimal" required') ?><?= sr_in('reason', $sf->t('f_reason'), '', 'text', 'required maxlength="255"') ?></div><button class="btn"><?= e($sf->t('inv_adjust')) ?></button></form>
<?php endif; ?>
<?php if ($i['stored_status'] !== 'cancelled'): ?><form method="post" action="<?= e($sf->url('/invoice/' . $id . '/do')) ?>" class="card" onsubmit="return confirm('<?= e($sf->t('confirm_cancel')) ?>')"><?= csrf_field() ?><input type="hidden" name="do" value="cancel"><h3><?= e($sf->t('inv_cancel')) ?></h3><?= sr_in('reason', $sf->t('f_reason'), '', 'text', 'required maxlength="255"') ?><button class="btn danger"><?= e($sf->t('inv_cancel')) ?></button></form><?php endif; ?></div><?php endif; ?>
<div class="card"><h3><?= e($sf->t($tenantView ? 'portal_confirm' : 'wrms_documents')) ?></h3>
  <?php if ($docs): ?><table><tbody><?php foreach ($docs as $d): ?><tr><td><a href="<?= e($sf->url('/doc/' . $d['id'])) ?>"><?= e($d['title']) ?></a> <small class="muted"><?= e($d['file_name']) ?></small> <?= $d['kind'] === 'confirmation' ? '<span class="badge info">' . e($sf->t('doc_confirmation')) . '</span>' : '' ?></td><td><?= e(sr_dt((int)$d['created_at'])) ?></td></tr><?php endforeach; ?></tbody></table><?php else: ?><p class="muted"><?= e($sf->t('none')) ?></p><?php endif; ?>
  <?php if ($canWrite || ($tenantView && $i['outstanding'] > 0)): ?><form method="post" enctype="multipart/form-data" action="<?= e($sf->url('/doc/upload')) ?>" class="sr-inline"><?= csrf_field() ?><input type="hidden" name="owner_type" value="invoice"><input type="hidden" name="owner_id" value="<?= $id ?>"><input type="hidden" name="back" value="<?= e('/p/storagerent/invoice/' . $id) ?>">
    <input name="title" placeholder="<?= e($sf->t($tenantView ? 'portal_confirm_note' : 'doc_title')) ?>" maxlength="190"><input type="file" name="file" required><button class="btn"><?= e($sf->t($tenantView ? 'portal_confirm_send' : 'upload')) ?></button></form><?php endif; ?></div>
